<?php
/** Proof — the bank accounts' settings, the opening-entry link, and the home's cash cards (spec "Proof", 5–6). */
require __DIR__ . '/lib.php';
$bea = as_member(27); $owner = as_member(1); $vera = as_member(26); $carl = as_member(28);
$w = cash_world();
pdo()->exec("SELECT set_config('app.member_id', '1', false)");
foreach (['1060' => 'SMOKE Settings bank', '1070' => 'SMOKE Settings savings'] as $code => $name) { if (!one('SELECT 1 FROM accounts WHERE code = :c', ['c' => $code])) { q("INSERT INTO accounts (code, name, account_type, subtype, is_bank, is_control, is_system) VALUES (:c, :n, 'asset', 'bank', true, false, false)", ['c' => $code, 'n' => $name]); } }
echo "1. Add and change\n";
[$c, $b] = act($bea, '/settings/banks/save.php', ['name' => 'SMOKE Nope', 'account' => account_id('1060')]);
ok($c === 403 && msg($b) === 'You may not change the ledger\'s settings.', 'a Bookkeeper saving: 403 in the right\'s sentence (settings.manage)');
ok(req('GET', '/settings/banks/', ['jar' => $vera])['code'] === 403 && req('GET', '/settings/banks/new', ['jar' => $bea])['code'] === 403, 'the settings screens are the administrator\'s: 403 for a Viewer and a Bookkeeper');
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/banks/save.php', ['name' => 'SMOKE Settings Bank', 'kind' => 'checking', 'account' => account_id('1060'), 'institution' => 'SMOKE Credit Union', 'account_last4' => '9876', 'currency' => 'usd', 'opening_balance' => '100.00', 'opening_date' => '2026-01-01']);
$sb = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $sb > 0 && ($b['location'] ?? '') === '/settings/banks/?notice=saved', "bank_account_save: 200, record_id $sb");
$row = q('SELECT * FROM bank_accounts WHERE id = :b', ['b' => $sb])[0];
ok($row['name'] === 'SMOKE Settings Bank' && $row['kind'] === 'checking' && $row['currency'] === 'USD' && $row['opening_balance'] === '100.00' && $row['opening_date'] === '2026-01-01' && $row['account_last4'] === '9876' && $row['institution'] === 'SMOKE Credit Union' && (int) $row['account_id'] === account_id('1060'), 'saved: USD, opening 100.00 on 2026-01-01, institution and last four');
$l = activity('bank_account.save', $since)[0]; $a = json_decode((string) $l['after'], true);
ok((int) $l['bank_account_id'] === $sb && $a['name'] === 'SMOKE Settings Bank' && $a['opening_balance'] === '100.00' && $a['currency'] === 'USD', 'bank_account.save logs bank_account_id and the fields');
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/banks/save.php', ['bank_account' => $sb, 'institution' => 'SMOKE Other CU']);
$r2 = q('SELECT * FROM bank_accounts WHERE id = :b', ['b' => $sb])[0];
ok($c === 200 && $r2['institution'] === 'SMOKE Other CU' && $r2['opening_balance'] === '100.00' && $r2['account_last4'] === '9876', 'a field left out stays as it was');
$l = activity('bank_account.save', $since)[0]; ok(array_keys(json_decode((string) $l['after'], true)) === ['institution'], 'the update logs only what changed');
echo "2. The guards\n";
[$c, $b] = act($owner, '/settings/banks/save.php', ['name' => 'SMOKE Over 6200', 'account' => account_id('6200')]);
ok($c === 422 && str_contains(msg($b), 'is not a bank account in the chart'), 'a bank account over 6200: 422 "Account 6200 … is not a bank account in the chart (is_bank)" (' . msg($b) . ')');
[$c, $b] = act($owner, '/settings/banks/save.php', ['name' => 'SMOKE Card Over Asset', 'kind' => 'credit_card', 'account' => account_id('1070')]);
ok($c === 422 && str_contains(msg($b), 'A credit card stands behind a liability account, not asset'), 'a card over an asset: 422 "A credit card stands behind a liability account, not asset"');
if (!one("SELECT 1 FROM accounts WHERE code = '2310'")) { q("INSERT INTO accounts (code, name, account_type, subtype, is_bank, is_control, is_system) VALUES ('2310', 'SMOKE Liability bank', 'liability', 'credit_card', true, false, false)"); }
[$c, $b] = act($owner, '/settings/banks/save.php', ['name' => 'SMOKE Checking Over Liability', 'kind' => 'checking', 'account' => account_id('2310')]);
ok($c === 422 && str_contains(msg($b), 'stands behind an asset account, not liability'), 'a checking account over a liability: 422');
[$c, $b] = act($owner, '/settings/banks/save.php', ['name' => 'smoke settings bank', 'account' => account_id('1070')]);
ok($c === 422 && str_contains(msg($b), 'A bank account named smoke settings bank exists'), 'a duplicate name: 422');
[$c, $b] = act($owner, '/settings/banks/save.php', ['name' => 'SMOKE Same Ledger', 'account' => account_id('1060')]);
ok($c === 422 && str_contains(msg($b), 'already stands behind another bank account'), 'one ledger account behind two bank accounts: 422');
[$c, $b] = act($owner, '/settings/banks/save.php', ['name' => '', 'kind' => 'wallet', 'currency' => 'dollars', 'opening_balance' => 'abc', 'opening_date' => 'x', 'account' => 424242, 'account_last4' => 'toolong']);
$f = fields($b);
ok($c === 422 && isset($f['name'], $f['kind'], $f['currency'], $f['opening_balance'], $f['opening_date'], $f['account'], $f['account_last4']), 'a bad form: 422 naming every field (' . json_encode(array_keys($f)) . ')');
echo "3. Fixed once there is something\n";
bank_line_row($sb, '2026-02-01', '5.00', 'SMOKE a line', 'SB-1');
[$c, $b] = act($owner, '/settings/banks/save.php', ['bank_account' => $sb, 'currency' => 'EUR']);
ok($c === 422 && str_contains(msg($b), 'The currency is fixed once SMOKE Settings Bank has lines or documents'), 'the currency is fixed once a line exists');
[$c, $b] = act($owner, '/settings/banks/archive.php', ['bank_account' => $sb]);
ok($c === 422 && str_contains(msg($b), 'has 1 unmatched bank line; match or ignore them first'), 'archive refused with an unmatched line');
$ln = (int) one('SELECT id FROM bank_transactions WHERE bank_account_id = :b', ['b' => $sb]);
act($bea, '/cash/ignore.php', ['bank_line' => $ln, 'reason' => 'SMOKE x']);
[$c, $b] = act($bea, '/cash/reconcile-start.php', ['bank_account' => $sb, 'statement_date' => '2026-03-31', 'statement_balance' => '100.00']);
$rec = (int) $b['record_id'];
[$c, $b] = act($owner, '/settings/banks/archive.php', ['bank_account' => $sb]);
ok($c === 422 && str_contains(msg($b), 'A reconciliation of SMOKE Settings Bank is in progress'), 'archive refused with a reconciliation in progress');
[$c, $b] = act($carl, '/cash/reconcile-complete.php', ['reconciliation' => $rec]);
ok($c === 200, 'the reconciliation completes (nothing matched; the ignored line counts for nothing: 100.00 = 100.00)');
[$c, $b] = act($owner, '/settings/banks/save.php', ['bank_account' => $sb, 'opening_balance' => '250.00']);
ok($c === 422 && str_contains(msg($b), 'is reconciled through 2026-03-31; the opening balance is fixed'), 'the opening balance is fixed once reconciled: 422 "… is reconciled through 2026-03-31; the opening balance is fixed"');
[$c, $b] = act($owner, '/settings/banks/save.php', ['bank_account' => $sb, 'opening_date' => '2026-01-02']);
ok($c === 422 && str_contains(msg($b), 'the opening balance is fixed'), 'and so is its date');
[$c, $b] = act($owner, '/settings/banks/save.php', ['bank_account' => $sb, 'name' => 'SMOKE Settings Bank (renamed)']);
ok($c === 200, 'but the name may change');
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/banks/archive.php', ['bank_account' => $sb]);
ok($c === 200 && (string) one('SELECT archived_at IS NOT NULL FROM bank_accounts WHERE id = :b', ['b' => $sb]) === '1' && count(activity('bank_account.archive', $since)) === 1, 'archived (no unmatched line, nothing in progress); bank_account.archive logged');
$body = page($owner, '/settings/banks/')['body'];
ok(str_contains($body, 'id="bank-setting-' . $sb . '"') && str_contains($body, 'archived'), 'the settings list shows it, archived');
[$c, $b] = act($owner, '/settings/banks/archive.php', ['bank_account' => $sb, 'archived' => 'no']);
ok($c === 200 && (string) one('SELECT archived_at IS NULL FROM bank_accounts WHERE id = :b', ['b' => $sb]) === '1', 'restored');
echo "4. The opening entry\n";
$body = page($owner, '/settings/banks/' . $sb . '/edit')['body'];
ok(str_contains($body, 'id="bank-form-opening-note"') && str_contains($body, 'DR the bank account / CR 3000 Owner equity') && str_contains($body, 'id="bank-form-opening-link"') && str_contains($body, '/journal/new?template=opening&amp;bank_account=' . $sb) && str_contains($body, 'id="bank-form-opening-fixed"'), 'the form explains the opening entry, links the prefilled entry form, and says the opening is fixed');
ok(preg_match('/name="opening_balance"[^>]*readonly/', $body) === 1, 'the opening balance field is read-only once reconciled');
$body = page($owner, '/journal/new?template=opening&bank_account=' . $sb . '&date=2026-01-01')['body'];
ok(str_contains($body, 'value="Opening balance — SMOKE Settings Bank (renamed)"') && preg_match('/<input[^>]*value="100.00"[^>]*id="entry-form-line-0-debit"/', $body) === 1 && preg_match('/<input[^>]*value="100.00"[^>]*id="entry-form-line-1-credit"/', $body) === 1 && str_contains($body, 'name="line_account[]" id="entry-form-line-0-account" value="' . account_id('1060') . '" data-picker-value') && str_contains($body, 'name="line_account[]" id="entry-form-line-1-account" value="' . account_id('3000') . '" data-picker-value'), 'slice 2\'s form opens prefilled: DR the bank\'s account 100.00 / CR 3000 Owner equity 100.00, the memo "Opening balance — …"');
$cardId = $w['card'];
$d = screen($owner, '/journal/new?template=opening&bank_account=' . $cardId)[1];
ok(($d['prefill']['lines'][0]['debit'] ?? 'x') === '0' && ($d['prefill']['memo'] ?? '') === 'Opening balance — SMOKE Card', 'a card with a zero opening: the prefill is by its own sign (JSON)');
echo "5. The pages\n";
$d = screen($owner, '/settings/banks/')[1];
ok(count($d['bank_accounts'] ?? []) >= 4 && isset($d['kinds']) && in_array('credit_card', $d['kinds'], true), 'JSON: the bank accounts of the settings and the kinds');
$d = screen($owner, '/settings/banks/' . $sb . '/edit')[1];
ok(($d['opening_fixed'] ?? false) === true && count($d['bank_ledger_accounts'] ?? []) >= 3, 'JSON: the form says the opening is fixed and offers the bank ledger accounts');
$body = page($bea, '/cash/')['body'];
ok(str_contains($body, 'id="bank-card-' . $w['chk'] . '"') && str_contains($body, 'id="banks-total-USD"') && str_contains($body, 'id="bank-card-' . $w['chk'] . '-import-btn"') && str_contains($body, 'id="bank-card-' . $w['card'] . '-kind"'), 'the cash page: a card per bank account, the total per currency, Import/Match/Reconcile, the kind chip');
$body = page($vera, '/cash/')['body'];
ok(str_contains($body, 'id="bank-card-' . $w['chk'] . '"') && !str_contains($body, 'id="bank-card-' . $w['chk'] . '-import-btn"'), 'a Viewer sees the cards, without the buttons');
echo "6. The home's cash cards and the trend\n";
$home = req('GET', '/', ['jar' => $vera])['body'];
ok(str_contains($home, 'id="home-cash-table"') && str_contains($home, 'id="home-cash-' . $w['chk'] . '"') && str_contains($home, 'id="home-cash-totals"') && str_contains($home, 'id="home-cash-total-USD"') && str_contains($home, 'id="home-cash-trend-table"'), 'the home: a row per bank account, the total per currency, the twelve-month table');
preg_match_all('/id="home-cash-trend-(\d{4}-\d{2}-\d{2})"/', $home, $m);
ok(count($m[1]) === 12 && $m[1][0] === date('Y-m-d') && $m[1][11] === date('Y-m-t', strtotime(date('Y-m-01') . ' -11 months')), 'twelve month rows, this month (to date) first');
$d = screen($vera, '/')[1];
ok(count($d['cash_trend']['months'] ?? []) === 12 && in_array($w['chk'], array_column($d['cash_trend']['accounts'] ?? [], 'bank_account_id'), true) && in_array('USD', array_column($d['cash_totals'] ?? [], 'currency'), true), 'JSON: cash_trend (12 months) and cash_totals');
$direct = (string) one("SELECT COALESCE(sum(l.debit - l.credit), 0) FROM journal_lines l JOIN journal_entries e ON e.id = l.entry_id AND e.status IN ('posted', 'reversed') WHERE l.account_id = :a AND e.entry_date <= '2026-05-31'", ['a' => account_id('1010')]);
$monthEnds = $d['cash_trend']['months']; $trendFigure = null;
foreach ($monthEnds as $me) { if ($me === '2026-05-31') { $trendFigure = $d['cash_trend']['rows'][$me][$w['chk']] ?? null; } }
ok($trendFigure === null || $trendFigure === $direct, 'a month-end figure equals the direct sum of the account\'s posted lines (' . var_export($trendFigure, true) . ' = ' . $direct . ')');
$ledgerNow = (string) one('SELECT ledger_balance FROM mcp_bank_accounts WHERE bank_account_id = :b', ['b' => $w['chk']]);
$cashRow = array_values(array_filter($d['cash'], fn ($x) => $x['bank_account_id'] === $w['chk']))[0] ?? [];
ok(($cashRow['ledger_balance'] ?? '') === $ledgerNow && ($cashRow['unmatched_lines'] ?? -1) === (int) one("SELECT count(*) FROM bank_transactions WHERE bank_account_id = :b AND status = 'unmatched'", ['b' => $w['chk']]), 'the home\'s Checking row: the ledger balance and the unmatched count agree with the account');
finish();
